// ============================================================================
// FreeLang ResultSet 모듈 - 쿼리 결과 저장 및 반환
// ============================================================================
// 목표: 쿼리 엔진에서 반환된 행들을 효율적으로 저장 및 관리
// 원리:
//   1. SoA 레이아웃: int_vals / str_vals / bool_vals 배열 분리 저장
//   2. 유연한 컬럼 수: col_count로 사용할 컬럼 수 지정
//   3. 에러 처리: has_error, error_code로 상태 관리
//   4. 타입별 접근: get_int / get_str / get_bool로 타입 안전 조회
// 구조:
//   - 상수 정의 (에러 코드, 제한값)
//   - ResultRow, ResultSet 구조체
//   - 기본 관리 함수 (new, clear)
//   - 행 추가 함수 (add_row_from_schema)
//   - 행 조회 함수 (get_row, get_int, get_str, get_bool)
//   - 메타데이터 함수 (get_row_count, get_col_count)
//   - 디버그 함수 (to_string)
// ============================================================================

module result_set {
    // === 상수 (에러 코드) ===
    const RESULT_OK:        i32 = 0;
    const RESULT_ERR_FULL:  i32 = 140;
    const RESULT_ERR_EMPTY: i32 = 141;

    // === 제한값 ===
    const MAX_RESULT_ROWS: i32 = 1024;
    const MAX_RESULT_COLS: i32 = 16;

    // === 데이터 구조체 ===

    // 결과 행 (SoA 레이아웃)
    struct ResultRow {
        int_vals:  [i64];
        str_vals:  [string];
        bool_vals: [bool];
        col_count: i32;
    }

    // 결과 집합
    struct ResultSet {
        rows:       [ResultRow];
        row_count:  i32;
        col_count:  i32;
        has_error:  bool;
        error_code: i32;
    }

    // === 생성 및 초기화 함수 ===

    // ResultSet 생성
    // col_count: 결과에 포함될 컬럼 수 (MAX_RESULT_COLS 이하)
    func result_set_new(col_count: i32) -> ResultSet {
        if col_count < 0 || col_count > MAX_RESULT_COLS {
            return ResultSet{
                rows:       make([ResultRow], 0),
                row_count:  0,
                col_count:  0,
                has_error:  true,
                error_code: RESULT_ERR_EMPTY,
            };
        }

        return ResultSet{
            rows:       make([ResultRow], MAX_RESULT_ROWS),
            row_count:  0,
            col_count:  col_count,
            has_error:  false,
            error_code: RESULT_OK,
        };
    }

    // ResultSet 초기화 (모든 행 제거)
    func (rs: *ResultSet) result_set_clear() -> i32 {
        // 기존 행들을 초기화
        let i = 0;
        for i = 0; i < rs.row_count; i = i + 1 {
            rs.rows[i] = ResultRow{
                int_vals:  make([i64], 0),
                str_vals:  make([string], 0),
                bool_vals: make([bool], 0),
                col_count: 0,
            };
        }
        rs.row_count = 0;
        rs.has_error = false;
        rs.error_code = RESULT_OK;
        return RESULT_OK;
    }

    // === 행 추가 함수 ===

    // 스키마를 기반으로 테이블의 특정 행을 결과 집합에 추가
    // row_idx: 테이블의 행 인덱스
    func (rs: *ResultSet) result_set_add_row_from_schema(t: schema.Table, row_idx: i32) -> i32 {
        // 용량 초과 확인
        if rs.row_count >= MAX_RESULT_ROWS {
            rs.has_error = true;
            rs.error_code = RESULT_ERR_FULL;
            return RESULT_ERR_FULL;
        }

        // 행 인덱스 범위 확인
        if row_idx < 0 || row_idx >= t.row_count {
            return RESULT_ERR_EMPTY;
        }

        // 테이블에서 행 추출
        let record = t.table_get_row(row_idx);

        // ResultRow 생성
        let new_row = ResultRow{
            int_vals:  make([i64],    MAX_RESULT_COLS),
            str_vals:  make([string], MAX_RESULT_COLS),
            bool_vals: make([bool],   MAX_RESULT_COLS),
            col_count: rs.col_count,
        };

        // 각 컬럼 타입별로 값 복사
        let int_idx = 0;
        let str_idx = 0;
        let bool_idx = 0;
        let col_idx = 0;

        for col_idx = 0; col_idx < t.schema.col_count; col_idx = col_idx + 1 {
            if col_idx >= rs.col_count {
                break;
            }

            let col_def = t.schema.col_defs[col_idx];

            if col_def.col_type == schema.COL_TYPE_INT {
                new_row.int_vals[int_idx] = record.int_vals[int_idx];
                int_idx = int_idx + 1;
            }

            if col_def.col_type == schema.COL_TYPE_STR {
                new_row.str_vals[str_idx] = record.str_vals[str_idx];
                str_idx = str_idx + 1;
            }

            if col_def.col_type == schema.COL_TYPE_BOOL {
                new_row.bool_vals[bool_idx] = record.bool_vals[bool_idx];
                bool_idx = bool_idx + 1;
            }
        }

        // ResultSet에 행 추가
        rs.rows[rs.row_count] = new_row;
        rs.row_count = rs.row_count + 1;

        return RESULT_OK;
    }

    // === 행 조회 함수 ===

    // 결과 집합에서 특정 행 조회
    func (rs: *ResultSet) result_set_get_row(idx: i32) -> (ResultRow, i32) {
        // 범위 확인
        if idx < 0 || idx >= rs.row_count {
            let empty_row = ResultRow{
                int_vals:  make([i64], 0),
                str_vals:  make([string], 0),
                bool_vals: make([bool], 0),
                col_count: 0,
            };
            return (empty_row, RESULT_ERR_EMPTY);
        }

        return (rs.rows[idx], RESULT_OK);
    }

    // 결과 집합에서 특정 행의 정수 값 조회
    func (rs: *ResultSet) result_set_get_int(row_idx: i32, col_idx: i32) -> (i64, i32) {
        // 행 범위 확인
        if row_idx < 0 || row_idx >= rs.row_count {
            return (0, RESULT_ERR_EMPTY);
        }

        let row = rs.rows[row_idx];

        // 컬럼 범위 확인
        if col_idx < 0 || col_idx >= row.col_count {
            return (0, RESULT_ERR_EMPTY);
        }

        // int_vals 배열에서 값 추출
        if col_idx < MAX_RESULT_COLS {
            return (row.int_vals[col_idx], RESULT_OK);
        }

        return (0, RESULT_ERR_EMPTY);
    }

    // 결과 집합에서 특정 행의 문자열 값 조회
    func (rs: *ResultSet) result_set_get_str(row_idx: i32, col_idx: i32) -> (string, i32) {
        // 행 범위 확인
        if row_idx < 0 || row_idx >= rs.row_count {
            return ("", RESULT_ERR_EMPTY);
        }

        let row = rs.rows[row_idx];

        // 컬럼 범위 확인
        if col_idx < 0 || col_idx >= row.col_count {
            return ("", RESULT_ERR_EMPTY);
        }

        // str_vals 배열에서 값 추출
        if col_idx < MAX_RESULT_COLS {
            return (row.str_vals[col_idx], RESULT_OK);
        }

        return ("", RESULT_ERR_EMPTY);
    }

    // === 메타데이터 함수 ===

    // 결과 집합의 행 개수 반환
    func (rs: *ResultSet) result_set_get_row_count() -> i32 {
        return rs.row_count;
    }

    // 결과 집합의 컬럼 개수 반환
    func (rs: *ResultSet) result_set_get_col_count() -> i32 {
        return rs.col_count;
    }

    // === 디버그 및 출력 함수 ===

    // ResultSet을 문자열로 변환 (디버깅용)
    // 형식: "Row 0: [val1, val2, ...]\nRow 1: ..."
    func (rs: *ResultSet) result_set_to_string() -> string {
        if rs.row_count == 0 {
            return "[Empty ResultSet]";
        }

        let output = "";
        let i = 0;

        for i = 0; i < rs.row_count; i = i + 1 {
            let row = rs.rows[i];

            // "Row i: ["
            output = output + "Row " + i32_to_str(i) + ": [";

            // 각 컬럼값 추가 (첫 5개만 표시하는 제약)
            let j = 0;
            for j = 0; j < row.col_count; j = j + 1 {
                if j > 0 {
                    output = output + ", ";
                }

                // int_vals에서 값 출력
                if j < MAX_RESULT_COLS {
                    let val = row.int_vals[j];
                    output = output + i64_to_str(val);
                }
            }

            output = output + "]\n";
        }

        return output;
    }

    // === 헬퍼 함수 ===

    // i32를 문자열로 변환
    @inline
    func i32_to_str(n: i32) -> string {
        if n == 0 { return "0"; }
        if n == 1 { return "1"; }
        if n == 2 { return "2"; }
        if n == 3 { return "3"; }
        if n == 4 { return "4"; }
        if n == 5 { return "5"; }
        if n == 6 { return "6"; }
        if n == 7 { return "7"; }
        if n == 8 { return "8"; }
        if n == 9 { return "9"; }
        if n < 0 { return "-" + i32_to_str(-n); }
        let d = n / 10;
        let r = n % 10;
        return i32_to_str(d) + i32_to_str(r);
    }

    // i64를 문자열로 변환
    @inline
    func i64_to_str(n: i64) -> string {
        if n == 0 { return "0"; }
        if n < 0 { return "-" + i64_to_str(-n); }
        return i32_to_str(i32(n));
    }
}

