//   7. result_set_to_string: 출력 형식 검증
// ============================================================================

module test_result_set {
    // === Test 1: ResultSet 생성 및 기본 검증 ===
    func test_result_set_new() -> bool {
        // 정상 케이스: col_count = 3
        let rs = result_set.result_set_new(3);
        if rs.col_count != 3 {
            return false;
        }
        if rs.row_count != 0 {
            return false;
        }
        if rs.has_error {
            return false;
        }
        if rs.error_code != result_set.RESULT_OK {
            return false;
        }

        // 경계 케이스: col_count = 0
        let rs2 = result_set.result_set_new(0);
        if rs2.col_count != 0 {
            return false;
        }

        // 경계 케이스: col_count = MAX_RESULT_COLS
        let rs3 = result_set.result_set_new(result_set.MAX_RESULT_COLS);
        if rs3.col_count != result_set.MAX_RESULT_COLS {
            return false;
        }

        // 에러 케이스: col_count > MAX_RESULT_COLS
        let rs4 = result_set.result_set_new(result_set.MAX_RESULT_COLS + 1);
        if !rs4.has_error {
            return false;
        }
        if rs4.error_code != result_set.RESULT_ERR_EMPTY {
